-- interview-batch1-diagrams.sql — 面試題庫補圖 批次 1（q7 / q12 / q17 / q19 / q26 / q27）
-- 圖為新繪，通過兩道驗證：
--   1) 瀏覽器 getBBox+getCTM 圖字重疊實測 = 0（含 path/polyline 逐段判定）
--   2) 幾何/語意驗證器 41 條斷言全過（工作週期真的是 30%、30%/70% 交點=解析解、Pd/η 自洽…）
-- 圖內標籤用英文/符號，四個語言欄位共用同一張圖（與既有 q5/q6/q28 一致）。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。
-- 冪等：欄位已含 <svg 就跳過，重跑不會插入第二張。

-- q7：SPI 四模式時序（CPOL × CPHA）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="350" viewBox="0 0 520 350" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="350" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">SPI has four modes, and CPOL / CPHA are the whole story</text><text x="10" y="88" fill="#1d2943" font-size="11" font-weight="bold">Mode 0</text><text x="10" y="104" fill="#64748b" font-size="11">CPOL 0 / CPHA 0</text><text x="10" y="120" fill="#15803d" font-size="11">most used</text><polyline points="120,104 150,104 150,76 190,76 190,104 230,104 230,76 270,76 270,104 310,104 310,76 350,76 350,104 390,104 390,76 430,76 430,104 470,104" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polygon points="145,61 155,61 150,70" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="225,61 235,61 230,70" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="305,61 315,61 310,70" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="385,61 395,61 390,70" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="10" y="148" fill="#1d2943" font-size="11" font-weight="bold">Mode 1</text><text x="10" y="164" fill="#64748b" font-size="11">CPOL 0 / CPHA 1</text><polyline points="120,164 150,164 150,136 190,136 190,164 230,164 230,136 270,136 270,164 310,164 310,136 350,136 350,164 390,164 390,136 430,136 430,164 470,164" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polygon points="185,121 195,121 190,130" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="265,121 275,121 270,130" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="345,121 355,121 350,130" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="425,121 435,121 430,130" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="10" y="208" fill="#1d2943" font-size="11" font-weight="bold">Mode 2</text><text x="10" y="224" fill="#64748b" font-size="11">CPOL 1 / CPHA 0</text><polyline points="120,196 150,196 150,224 190,224 190,196 230,196 230,224 270,224 270,196 310,196 310,224 350,224 350,196 390,196 390,224 430,224 430,196 470,196" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polygon points="145,181 155,181 150,190" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="225,181 235,181 230,190" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="305,181 315,181 310,190" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="385,181 395,181 390,190" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="10" y="268" fill="#1d2943" font-size="11" font-weight="bold">Mode 3</text><text x="10" y="284" fill="#64748b" font-size="11">CPOL 1 / CPHA 1</text><polyline points="120,256 150,256 150,284 190,284 190,256 230,256 230,284 270,284 270,256 310,256 310,284 350,284 350,256 390,256 390,284 430,284 430,256 470,256" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><polygon points="185,241 195,241 190,250" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="265,241 275,241 270,250" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="345,241 355,241 350,250" fill="#b45309" stroke="#b45309" stroke-width="1"/><polygon points="425,241 435,241 430,250" fill="#b45309" stroke="#b45309" stroke-width="1"/><text x="150" y="302" fill="#b45309" font-size="11">triangles = the edge that samples the data</text><text x="10" y="320" fill="#1d2943" font-size="11">CPOL sets the idle level of SCLK. CPHA picks which edge samples.</text><text x="10" y="340" fill="#64748b" font-size="11">Master and slave must agree on the mode, or every byte comes back wrong.</text></svg></div>$vsq$ || answer else answer end,
