-- q19：LDO 壓降損耗與效率
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">LDO at 500mA: the drop becomes heat</text><g data-sym="rail"><line x1="70" y1="56" x2="70" y2="68" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="62" y1="56" x2="78" y2="56" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="82" y="62" fill="#b91c1c" font-size="11" font-weight="bold">VIN 5V</text><line x1="70" y1="68" x2="70" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="70" y1="120" x2="125" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ic"><rect x="125" y="88" width="110" height="64" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="180" y="116" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">LDO</text><text x="180" y="134" fill="#64748b" font-size="11" text-anchor="middle">linear pass FET</text><line x1="235" y1="120" x2="300" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="300" cy="120" r="2.6" fill="#1f4fd1"/></g><text x="242" y="112" fill="#1d2943" font-size="11">500mA</text><text x="306" y="116" fill="#15803d" font-size="11" font-weight="bold">3.3V</text><g data-sym="resistor"><line x1="300" y1="136" x2="300" y2="148" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="300,148 293,151 307,157 293,163 307,169 300,172" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="300" y1="172" x2="300" y2="184" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="300" y1="120" x2="300" y2="136" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="300" y1="184" x2="300" y2="200" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="300" y1="200" x2="300" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="288" y1="214" x2="312" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="292" y1="219" x2="308" y2="219" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="296" y1="224" x2="304" y2="224" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="312" y="156" fill="#64748b" font-size="11">load</text><line x1="340" y1="60" x2="340" y2="240" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><rect x="360" y="90" width="40" height="48" fill="#b91c1c" opacity="0.18" stroke="#b91c1c" stroke-width="1.4"/><rect x="360" y="138" width="40" height="92" fill="#15803d" opacity="0.18" stroke="#15803d" stroke-width="1.4"/><text x="380" y="80" fill="#1d2943" font-size="11" text-anchor="middle">2.5W in</text><text x="408" y="118" fill="#b91c1c" font-size="11">0.85W heat</text><text x="408" y="188" fill="#15803d" font-size="11">1.65W out</text><text x="380" y="250" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">66% efficient</text><text x="10" y="290" fill="#1d2943" font-size="11">Ploss = (VIN - VOUT) x IL = 1.7V x 0.5A = 0.85W, and efficiency is just VOUT/VIN.</text><text x="10" y="310" fill="#64748b" font-size="11">That 0.85W is heat: TJ = 25 + 0.85 x 50 = 67.5 C at 50 C/W. Bigger drop -> use a buck.</text></svg></div>$vsq$ || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">LDO at 500mA: the drop becomes heat</text><g data-sym="rail"><line x1="70" y1="56" x2="70" y2="68" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="62" y1="56" x2="78" y2="56" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="82" y="62" fill="#b91c1c" font-size="11" font-weight="bold">VIN 5V</text><line x1="70" y1="68" x2="70" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="70" y1="120" x2="125" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ic"><rect x="125" y="88" width="110" height="64" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="180" y="116" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">LDO</text><text x="180" y="134" fill="#64748b" font-size="11" text-anchor="middle">linear pass FET</text><line x1="235" y1="120" x2="300" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="300" cy="120" r="2.6" fill="#1f4fd1"/></g><text x="242" y="112" fill="#1d2943" font-size="11">500mA</text><text x="306" y="116" fill="#15803d" font-size="11" font-weight="bold">3.3V</text><g data-sym="resistor"><line x1="300" y1="136" x2="300" y2="148" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="300,148 293,151 307,157 293,163 307,169 300,172" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="300" y1="172" x2="300" y2="184" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="300" y1="120" x2="300" y2="136" stroke="#1f4fd1" stroke-width="2" stroke-linecap="ro