-- q26：RC 低通：fc 與 -3dB 轉角
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">RC low-pass: where the corner is and how fast it falls</text><text x="14" y="124" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">IN</text><line x1="20" y1="120" x2="36" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="36" y1="120" x2="48" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="48,120 51,113 57,127 63,113 69,127 72,120" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="72" y1="120" x2="84" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="84" y1="120" x2="140" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="60" y="102" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">R 10k</text><g data-sym="junction"><circle cx="140" cy="120" r="2.6" fill="#1f4fd1"/></g><g data-sym="capacitor"><line x1="140" y1="138" x2="140" y2="155" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="129" y1="155" x2="151" y2="155" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="129" y1="165" x2="151" y2="165" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="140" y1="165" x2="140" y2="182" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="140" y1="120" x2="140" y2="138" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="140" y1="182" x2="140" y2="200" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="140" y1="200" x2="140" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/>