-- q27：Setup / Hold 視窗
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Setup and hold: the window around the sampling edge</text><text x="6" y="114" fill="#1d2943" font-size="11" font-weight="bold">CLK</text><polyline points="40,130 260,130 260,90 340,90 340,130 480,130" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="6" y="204" fill="#1d2943" font-size="11" font-weight="bold">DATA</text><polyline points="40,220 200,220 200,180 320,180 320,220 480,220" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="260" y1="86" x2="260" y2="248" stroke="#94a3b8" stroke-width="1.4" stroke-dasharray="5 4"/><text x="268" y="82" fill="#64748b" font-size="11">sampling edge</text><line x1="200" y1="248" x2="260" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="200" y1="244" x2="200" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="260" y1="244" x2="260" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="230" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">tsu</text><line x1="260" y1="248" x2="320" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="320" y1="244" x2="320" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="290" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">th</text><text x="340" y="200" fill="#64748b" font-size="11">data must sit still across both</text><text x="10" y="292" fill="#1d2943" font-size="11">Setup slack = Tclk - Tco - Tcomb - tsu >= 0. Fix it with a slower clock or less logic.</text><text x="10" y="312" fill="#64748b" font-size="11">Hold slack = Tco + Tcomb - th >= 0. Fix it with delay. Violate either -> metastability.</text></svg></div>$vsq$ || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Setup and hold: the window around the sampling edge</text><text x="6" y="114" fill="#1d2943" font-size="11" font-weight="bold">CLK</text><polyline points="40,130 260,130 260,90 340,90 340,130 480,130" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="6" y="204" fill="#1d2943" font-size="11" font-weight="bold">DATA</text><polyline points="40,220 200,220 200,180 320,180 320,220 480,220" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="260" y1="86" x2="260" y2="248" stroke="#94a3b8" stroke-width="1.4" stroke-dasharray="5 4"/><text x="268" y="82" fill="#64748b" font-size="11">sampling edge</text><line x1="200" y1="248" x2="260" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="200" y1="244" x2="200" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="260" y1="244" x2="260" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="230" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">tsu</text><line x1="260" y1="248" x2="320" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="320" y1="244" x2="320" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="290" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">th</text><text x="340" y="200" fill="#64748b" font-size="11">data must sit still across both</text><text x="10" y="292" fill="#1d2943" font-size="11">Setup slack = Tclk - Tco - Tcomb - tsu >= 0. Fix it with a slower clock or less logic.</text><text x="10" y="312" fill="#64748b" font-size="11">Hold slack = Tco + Tcomb - th >= 0. Fix it with delay. Violate either -> metastability.</text></svg></div>$vsq$ || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Setup and hold: the window around the sampling edge</text><text x="6" y="114" fill="#1d2943" font-size="11" font-weight="bold">CLK</text><polyline points="40,130 260,130 260,90 340,90 340,130 480,130" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="6" y="204" fill="#1d2943" font-size="11" font-weight="bold">DATA</text><polyline points="40,220 200,220 200,180 320,180 320,220 480,220" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="260" y1="86" x2="260" y2="248" stroke="#94a3b8" stroke-width="1.4" stroke-dasharray="5 4"/><text x="268" y="82" fill="#64748b" font-size="11">sampling edge</text><line x1="200" y1="248" x2="260" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="200" y1="244" x2="200" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="260" y1="244" x2="260" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="230" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">tsu</text><line x1="260" y1="248" x2="320" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="320" y1="244" x2="320" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="290" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">th</text><text x="340" y="200" fill="#64748b" font-size="11">data must sit still across both</text><text x="10" y="292" fill="#1d2943" font-size="11">Setup slack = Tclk - Tco - Tcomb - tsu >= 0. Fix it with a slower clock or less logic.</text><text x="10" y="312" fill="#64748b" font-size="11">Hold slack = Tco + Tcomb - th >= 0. Fix it with delay. Violate either -> metastability.</text></svg></div>$vsq$ || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Setup and hold: the window around the sampling edge</text><text x="6" y="114" fill="#1d2943" font-size="11" font-weight="bold">CLK</text><polyline points="40,130 260,130 260,90 340,90 340,130 480,130" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="6" y="204" fill="#1d2943" font-size="11" font-weight="bold">DATA</text><polyline points="40,220 200,220 200,180 320,180 320,220 480,220" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="260" y1="86" x2="260" y2="248" stroke="#94a3b8" stroke-width="1.4" stroke-dasharray="5 4"/><text x="268" y="82" fill="#64748b" font-size="11">sampling edge</text><line x1="200" y1="248" x2="260" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="200" y1="244" x2="200" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="260" y1="244" x2="260" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="230" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">tsu</text><line x1="260" y1="248" x2="320" y2="248" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><line x1="320" y1="244" x2="320" y2="252" stroke="#15803d" stroke-width="1.4" stroke-linecap="round"/><text x="290" y="266" fill="#15803d" font-size="11" text-anchor="middle" font-weight="bold">th</text><text x="340" y="200" fill="#64748b" font-size="11">data must sit still across both</text><text x="10" y="292" fill="#1d2943" font-size="11">Setup slack = Tclk - Tco - Tcomb - tsu >= 0. Fix it with a slower clock or less logic.</text><text x="10" y="312" fill="#64748b" font-size="11">Hold slack = Tco + Tcomb - th >= 0. Fix it with delay. Violate either -> metastability.</text></svg></div>$vsq$ || answer_ko else answer_ko end
 where question like $q$%Setup Time 和 Hold Time%$q$;

-- 驗收：六列都要 zh/en 為 t（ja/ko 若原本沒譯文會是 null，屬正常）
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%SPI Mode 會有幾種格式%$q$
    or question like $q$%請算出該 Buck 線路的%$q$
    or question like $q$%目標 tr = 300ns%$q$
    or question like $q$%一個 LDO 輸入 5V，輸出 3.3V%$q$
    or question like $q$%RC 低通濾波器%$q$
    or question like $q$%Setup Time 和 Hold Time%$q$;
